    height: 1.25rem;
    border: 2px solid var(--text-secondary);
    border-radius: 4px;
    background-color: transparent;
    cursor: pointer;
    position: relative;
    flex-shrink: 0;
    margin-top: 0.1rem;
}

input[type="checkbox"]:checked {
    background-color: var(--accent-color);
    border-color: var(--accent-color);
}

input[type="checkbox"]:checked::after {
    content: "";
    position: absolute;
    left: 6px;
    top: 2px;
    width: 5px;
    height: 10px;
    border: solid var(--bg-color);
    border-width: 0 2px 2px 0;
    transform: rotate(45deg);
}

input[type="checkbox"]:focus {
    outline: 2px solid var(--focus-outline);
    outline-offset: 2px;
}

label {
    font-size: 1rem;
    cursor: pointer;
    line-height: 1.4;
}

label a {
    color: var(--accent-color);
    text-decoration: none;
}

label a:hover, label a:focus {
    text-decoration: underline;
    outline: none;
    color: var(--accent-hover);
}

.required-marker {
    color: var(--error-color);
    margin-left: 0.25rem;
}

.helper-text {
    font-size: 0.875rem;
    color: var(--text-secondary);
    margin-top: 0.25rem;
    margin-bottom: 0;
}

.error-text {
    font-size: 0.875rem;
    color: var(--error-color);
    margin-top: 0.5rem;
    font-weight: 500;
}

[hidden] {
    display: none;
}

button {
    width: 100%;
    padding: 0.75rem;
    border-radius: 4px;
    border: none;
    background-color: var(--accent-color);
    color: var(--bg-color);
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s;
}

button:hover {
    background-color: var(--accent-hover);
}

button:focus {
    outline: 2px solid var(--focus-outline);
    outline-offset: 2px;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    border: 0;
